1	package server
2	
3	import (
4		"encoding/json"
5		"net/http"
6		"sort"
7		"unicode/utf8"
8	)
9	
10	const (
11		mailboxAnalyzePath = "/v1/schedules/mailbox/analyze"
12		maxMailboxes       = 256
13		maxMailboxCapacity = 65535
14		maxMailboxActions  = 1024
15		maxMessageRunes    = 256
16	)
17	
18	// Mailbox action discriminators.
19	const (
20		mboxActRun int = iota
21		mboxActSend
22		mboxActReceive
23	)
24	
25	type mboxSendIn struct {
26		Mailbox string `json:"mailbox"`
27		Message string `json:"message"`
28	}
29	
30	type mboxActionIn struct {
31		Run     *int64      `json:"run"`
32		Send    *mboxSendIn `json:"send"`
33		Receive *string     `json:"receive"`
34	}
35	
36	type mboxTaskIn struct {
37		ID       string          `json:"id"`
38		Priority *int64          `json:"priority"`
39		Release  *int64          `json:"release"`
40		Deadline *int64          `json:"deadline"`
41		Actions  *[]mboxActionIn `json:"actions"`
42	}
43	
44	type mboxMailboxIn struct {
45		Name     string `json:"name"`
46		Capacity *int64 `json:"capacity"`
47	}
48	
49	type mboxRequest struct {
50		Horizon   *int64           `json:"horizon"`
51		Mailboxes *[]mboxMailboxIn `json:"mailboxes"`
52		Tasks     *[]mboxTaskIn    `json:"tasks"`
53	}
54	
55	type mboxAction struct {
56		kind    int
57		run     int64
58		mailbox string // send/receive target
59		message string // send payload
60	}
61	
62	type mboxTask struct {
63		id       string
64		priority int64
65		release  int64
66		deadline int64
67		actions  []mboxAction
68	}
69	
70	type mboxTimelineInterval struct {
71		TaskID string `json:"taskId"`
72		Start  int64  `json:"start"`
73		End    int64  `json:"end"`
74	}
75	
76	type mboxReceived struct {
77		Mailbox string `json:"mailbox"`
78		Message string `json:"message"`
79		Time    int64  `json:"time"`
80	}
81	
82	type mboxTaskResult struct {
83		Executed       int64          `json:"executed"`
84		Completion     *int64         `json:"completion"`
85		State          string         `json:"state"`
86		BlockedAction  *string        `json:"blockedAction"`
87		BlockedOn      *string        `json:"blockedOn"`
88		Received       []mboxReceived `json:"received"`
89		DeadlineStatus string         `json:"deadlineStatus"`
90	}
91	
92	type mboxResponse struct {
93		Status    string                 `json:"status"`
94		StoppedAt int64                  `json:"stoppedAt"`
95		Timeline  []mboxTimelineInterval `json:"timeline"`
96		Results   []mboxTaskResult       `json:"results"`
97	}
98	
99	func handleMailboxAnalyze(w http.ResponseWriter, r *http.Request) {
100		if r.Method != http.MethodPost {
101			w.Header().Set("Allow", http.MethodPost)
102			writeAnalyzeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
103			return
104		}
105		var req mboxRequest
106		if !decodeStrictJSON(w, r, &req) {
107			return
108		}
109		tasks, capacity, ok := validateMailboxRequest(&req)
110		if !ok {
111			writeAnalyzeError(w, http.StatusUnprocessableEntity, "validation_failed")
112			return
113		}
114		w.Header().Set("Content-Type", "application/json; charset=utf-8")
115		w.WriteHeader(http.StatusOK)
116		_ = json.NewEncoder(w).Encode(simulateMailbox(tasks, capacity, *req.Horizon))
117	}
118	
119	// validateMailboxRequest enforces the one-shot task constraints (without
120	// execution), the mailbox declarations (1..256 unique id-shaped names with
121	// capacity 1..65535) and the action-program rules: exactly one verb per
122	// action, positive run microseconds, send/receive references pointing at
123	// declared mailboxes, messages of 1..256 Unicode code points, and per-task
124	// and global run totals that fit int64.
125	func validateMailboxRequest(req *mboxRequest) ([]mboxTask, map[string]int64, bool) {
126		if req.Horizon == nil || *req.Horizon <= 0 || *req.Horizon > maxHorizon {
127			return nil, nil, false
128		}
129		if req.Mailboxes == nil || len(*req.Mailboxes) == 0 || len(*req.Mailboxes) > maxMailboxes {
130			return nil, nil, false
131		}
132		capacity := make(map[string]int64, len(*req.Mailboxes))
133		for i := range *req.Mailboxes {
134			mb := (*req.Mailboxes)[i]
135			if !validTaskID(mb.Name) {
136				return nil, nil, false
137			}
138			if _, dup := capacity[mb.Name]; dup {
139				return nil, nil, false
140			}
141			if mb.Capacity == nil || *mb.Capacity < 1 || *mb.Capacity > maxMailboxCapacity {
142				return nil, nil, false
143			}
144			capacity[mb.Name] = *mb.Capacity
145		}
146		if req.Tasks == nil || len(*req.Tasks) == 0 || len(*req.Tasks) > maxTasks {
147			return nil, nil, false
148		}
149		horizon := *req.Horizon
150		tasks := make([]mboxTask, 0, len(*req.Tasks))
151		ids := make(map[string]struct{}, len(*req.Tasks))
152		var totalRun int64
153		for i := range *req.Tasks {
154			in := (*req.Tasks)[i]
155			if !validTaskID(in.ID) {
156				return nil, nil, false
157			}
158			if _, dup := ids[in.ID]; dup {
159				return nil, nil, false
160			}
161			ids[in.ID] = struct{}{}
162			if in.Priority == nil || *in.Priority < 0 || *in.Priority > 255 {
163				return nil, nil, false
164			}
165			if in.Release == nil || *in.Release < 0 || *in.Release >= horizon {
166				return nil, nil, false
167			}
168			if in.Deadline == nil || *in.Deadline <= *in.Release {
169				return nil, nil, false
170			}
171			if in.Actions == nil || len(*in.Actions) == 0 || len(*in.Actions) > maxMailboxActions {
172				return nil, nil, false
173			}
174	
175			actions := make([]mboxAction, 0, len(*in.Actions))
176			var taskRun int64
177			for j := range *in.Actions {
178				ai := (*in.Actions)[j]
179				verbs := 0
180				if ai.Run != nil {
181					verbs++
182				}
183				if ai.Send != nil {
184					verbs++
185				}
186				if ai.Receive != nil {
187					verbs++
188				}
189				if verbs != 1 {
190					return nil, nil, false
191				}
192				switch {
193				case ai.Run != nil:
194					if *ai.Run <= 0 {
195						return nil, nil, false
196					}
197					var ok bool
198					taskRun, ok = saturatingAdd(taskRun, *ai.Run)
199					if !ok {
200						return nil, nil, false
201					}
202					actions = append(actions, mboxAction{kind: mboxActRun, run: *ai.Run})
203				case ai.Send != nil:
204					name := ai.Send.Mailbox
205					if _, ok := capacity[name]; !ok {
206						return nil, nil, false
207					}
208					if n := utf8.RuneCountInString(ai.Send.Message); n < 1 || n > maxMessageRunes {
209						return nil, nil, false
210					}
211					actions = append(actions, mboxAction{kind: mboxActSend, mailbox: name, message: ai.Send.Message})
212				default:
213					name := *ai.Receive
214					if _, ok := capacity[name]; !ok {
215						return nil, nil, false
216					}
217					actions = append(actions, mboxAction{kind: mboxActReceive, mailbox: name})
218				}
219			}
220			var ok bool
221			totalRun, ok = saturatingAdd(totalRun, taskRun)
222			if !ok {
223				return nil, nil, false
224			}
225			tasks = append(tasks, mboxTask{
226				id:       in.ID,
227				priority: *in.Priority,
228				release:  *in.Release,
229				deadline: *in.Deadline,
230				actions:  actions,
231			})
232		}
233		return tasks, capacity, true
234	}
235	
236	// mboxSegment is an unmerged run interval recorded by the simulation.
237	type mboxSegment struct {
238		index      int
239		start, end int64
240	}
241	
242	// mboxSim is an event-driven single-core simulation of bounded FIFO
243	// mailboxes. Time advances only through run actions; send, receive and
244	// completion happen at a single instant. Communication never alters
245	// priorities. Two invariants hold per mailbox: blocked receivers imply an
246	// empty queue (a send always prefers direct delivery), and blocked senders
247	// imply a full queue (a receive from a full mailbox immediately refills it
248	// from the earliest blocked sender).
249	type mboxSim struct {
250		tasks    []mboxTask
251		n        int
252		horizon  int64
253		capacity map[string]int64
254	
255		queue     map[string][]string // mailbox -> queued messages, head first
256		senders   map[string][]int    // mailbox -> tasks blocked sending
257		receivers map[string][]int    // mailbox -> tasks blocked receiving
258	
259		blockedWhat []string // "send"/"receive" when blocked, "" otherwise
260		blockedM    []string // mailbox name when blocked, "" otherwise
261		blockTime   []int64
262		pc          []int   // next action to interpret
263		runRem      []int64 // remainder of the run action at pc
264	
265		released   []bool
266		completed  []bool
267		executed   []int64
268		completion []*int64
269		received   [][]mboxReceived
270	
271		order   []int // tasks sorted by (release, input index)
272		nextRel int
273		segs    []mboxSegment
274		current int
275		now     int64
276	}
277	
278	func simulateMailbox(tasks []mboxTask, capacity map[string]int64, horizon int64) mboxResponse {
279		n := len(tasks)
280		s := &mboxSim{
281			tasks:       tasks,
282			n:           n,
283			horizon:     horizon,
284			capacity:    capacity,
285			queue:       make(map[string][]string),
286			senders:     make(map[string][]int),
287			receivers:   make(map[string][]int),
288			blockedWhat: make([]string, n),
289			blockedM:    make([]string, n),
290			blockTime:   make([]int64, n),
291			pc:          make([]int, n),
292			runRem:      make([]int64, n),
293			released:    make([]bool, n),
294			completed:   make([]bool, n),
295			executed:    make([]int64, n),
296			completion:  make([]*int64, n),
297			received:    make([][]mboxReceived, n),
298			current:     -1,
299		}
300		s.order = make([]int, n)
301		for i := range s.order {
302			s.order[i] = i
303		}
304		sort.Slice(s.order, func(a, b int) bool {
305			ia, ib := s.order[a], s.order[b]
306			if tasks[ia].release != tasks[ib].release {
307				return tasks[ia].release < tasks[ib].release
308			}
309			return ia < ib
310		})
311	
312		stalled := false
313	loop:
314		for {
315			s.releaseUpTo()
316	
317			// After any state change, first drain the current task's consecutive
318			// zero-duration actions, then schedule.
319			if s.current != -1 {
320				s.settle(s.current)
321				if !s.runnable(s.current) {
322					s.current = -1
323				}
324			}
325	
326			if s.current == -1 {
327				best := s.pickBest()
328				if best == -1 {
329					// Nothing runnable: with no pending release every unfinished
330					// task is blocked, so the simulation stalls here; otherwise
331					// jump to the next release.
332					if s.nextRel >= n {
333						stalled = !s.allCompleted()
334						break loop
335					}
336					s.now = tasks[s.order[s.nextRel]].release
337					continue
338				}
339				s.current = best
340				s.settle(best)
341				if !s.runnable(best) {
342					s.current = -1
343					continue
344				}
345			}
346	
347			// A freshly selected task's zero-duration chain can unblock a strictly
348			// higher-priority task at the same instant. Re-resolve until the
349			// selection is stable; equal priority never preempts.
350			for {
351				best := s.pickBest()
352				if best != -1 && best != s.current && tasks[best].priority < tasks[s.current].priority {
353					s.current = best
354					s.settle(best)
355					if !s.runnable(best) {
356						s.current = -1
357						continue loop
358					}
359					continue
360				}
361				break
362			}
363	
364			if s.now >= horizon {
365				break
366			}
367			cur := s.current
368			// Advance until the run completes, the horizon cuts it, or a strictly
369			// higher-priority task releases.
370			rem := s.runRem[cur]
371			length := rem
372			if avail := horizon - s.now; length > avail {
373				length = avail
374			}
375			end := s.now + length
376			for k := s.nextRel; k < n; k++ {
377				j := s.order[k]
378				if tasks[j].priority < tasks[cur].priority &&
379					tasks[j].release > s.now && tasks[j].release < end {
380					end = tasks[j].release
381				}
382			}
383			s.segs = append(s.segs, mboxSegment{index: cur, start: s.now, end: end})
384			delta := end - s.now
385			s.executed[cur] += delta
386			s.now = end
387			if rem -= delta; rem > 0 {
388				s.runRem[cur] = rem
389				continue
390			}
391			s.runRem[cur] = 0
392			s.pc[cur]++
393			if s.now >= horizon {
394				// The run ends exactly at the horizon: matching the one-shot
395				// baseline, releases strictly before the horizon are already in
396				// effect, so account for them before draining this task's trailing
397				// zero-duration actions once. Nothing else gets to run.
398				s.releaseUpTo()
399				s.settle(cur)
400				break
401			}
402		}
403	
404		return s.buildResponse(stalled)
405	}
406	
407	// settle drains the task's consecutive zero-duration actions. It stops when
408	// the task faces a run action (arming its remainder), blocks, or completes.
409	func (s *mboxSim) settle(i int) {
410		for {
411			t := s.tasks[i]
412			if s.pc[i] >= len(t.actions) {
413				s.completed[i] = true
414				now := s.now
415				s.completion[i] = &now
416				return
417			}
418			a := t.actions[s.pc[i]]
419			switch a.kind {
420			case mboxActRun:
421				if s.runRem[i] == 0 {
422					s.runRem[i] = a.run
423				}
424				return
425			case mboxActSend:
426				m := a.mailbox
427				// Direct delivery to the earliest blocked receiver wins over
428				// queuing; the message never enters the queue.
429				if rs := s.receivers[m]; len(rs) > 0 {
430					w := earliestBlocked(rs, s.blockTime)
431					s.receivers[m] = removeBlocked(rs, w)
432					s.unblock(w)
433					s.received[w] = append(s.received[w], mboxReceived{Mailbox: m, Message: a.message, Time: s.now})
434					s.pc[i]++
435					continue
436				}
437				if int64(len(s.queue[m])) < s.capacity[m] {
438					s.queue[m] = append(s.queue[m], a.message)
439					s.pc[i]++
440					continue
441				}
442				// Full mailbox: the sender blocks, carrying its message.
443				s.block(i, "send", m)
444				return
445			case mboxActReceive:
446				m := a.mailbox
447				q := s.queue[m]
448				if len(q) == 0 {
449					s.block(i, "receive", m)
450					return
451				}
452				s.queue[m] = q[1:]
453				s.received[i] = append(s.received[i], mboxReceived{Mailbox: m, Message: q[0], Time: s.now})
454				// If the mailbox was full, the earliest blocked sender's message
455				// immediately moves to the tail and that sender unblocks.
456				if int64(len(q)) == s.capacity[m] {
457					if sd := s.senders[m]; len(sd) > 0 {
458						w := earliestBlocked(sd, s.blockTime)
459						s.senders[m] = removeBlocked(sd, w)
460						s.queue[m] = append(s.queue[m], s.tasks[w].actions[s.pc[w]].message)
461						s.unblock(w)
462					}
463				}
464				s.pc[i]++
465			}
466		}
467	}
468	
469	// block parks the task on a mailbox; its pc stays on the blocking action
470	// until unblock completes it.
471	func (s *mboxSim) block(i int, what, m string) {
472		s.blockedWhat[i] = what
473		s.blockedM[i] = m
474		s.blockTime[i] = s.now
475		if what == "send" {
476			s.senders[m] = append(s.senders[m], i)
477		} else {
478			s.receivers[m] = append(s.receivers[m], i)
479		}
480	}
481	
482	// unblock releases a blocked task whose send or receive has been satisfied by
483	// another task's action, advancing it past the completed action.
484	func (s *mboxSim) unblock(i int) {
485		s.blockedWhat[i] = ""
486		s.blockedM[i] = ""
487		s.pc[i]++
488	}
489	
490	// earliestBlocked picks the task with the earliest block time, breaking ties
491	// at the same instant by input order.
492	func earliestBlocked(list []int, blockTime []int64) int {
493		w := list[0]
494		for _, x := range list[1:] {
495			if blockTime[x] < blockTime[w] || (blockTime[x] == blockTime[w] && x < w) {
496				w = x
497			}
498		}
499		return w
500	}
501	
502	func removeBlocked(list []int, x int) []int {
503		for k, v := range list {
504			if v == x {
505				return append(list[:k], list[k+1:]...)
506			}
507		}
508		return list
509	}
510	
511	// pickBest selects the runnable task with the highest priority, breaking ties
512	// by release time then input index.
513	func (s *mboxSim) pickBest() int {
514		best := -1
515		for i := 0; i < s.n; i++ {
516			if !s.released[i] || s.completed[i] || s.blockedM[i] != "" {
517				continue
518			}
519			if best == -1 {
520				best = i
521				continue
522			}
523			a, b := s.tasks[i], s.tasks[best]
524			if a.priority < b.priority ||
525				(a.priority == b.priority && a.release < b.release) ||
526				(a.priority == b.priority && a.release == b.release && i < best) {
527				best = i
528			}
529		}
530		return best
531	}
532	
533	func (s *mboxSim) runnable(i int) bool {
534		return s.released[i] && !s.completed[i] && s.blockedM[i] == "" && s.runRem[i] > 0
535	}
536	
537	func (s *mboxSim) releaseUpTo() {
538		for s.nextRel < s.n && s.tasks[s.order[s.nextRel]].release <= s.now {
539			s.released[s.order[s.nextRel]] = true
540			s.nextRel++
541		}
542	}
543	
544	func (s *mboxSim) allCompleted() bool {
545		for i := 0; i < s.n; i++ {
546			if !s.completed[i] {
547				return false
548			}
549		}
550		return true
551	}
552	
553	func (s *mboxSim) buildResponse(stalled bool) mboxResponse {
554		timeline := make([]mboxTimelineInterval, 0, len(s.segs))
555		for _, seg := range s.segs {
556			last := len(timeline) - 1
557			if last >= 0 &&
558				timeline[last].TaskID == s.tasks[seg.index].id &&
559				timeline[last].End == seg.start {
560				timeline[last].End = seg.end
561				continue
562			}
563			timeline = append(timeline, mboxTimelineInterval{
564				TaskID: s.tasks[seg.index].id,
565				Start:  seg.start,
566				End:    seg.end,
567			})
568		}
569	
570		results := make([]mboxTaskResult, s.n)
571		for i, t := range s.tasks {
572			state := "ready"
573			switch {
574			case s.completed[i]:
575				state = "completed"
576			case s.blockedM[i] != "":
577				state = "blocked"
578			case !s.released[i]:
579				state = "unreleased"
580			}
581			var blockedAction, blockedOn *string
582			if state == "blocked" {
583				what := s.blockedWhat[i]
584				blockedAction = &what
585				m := s.blockedM[i]
586				blockedOn = &m
587			}
588			var deadlineStatus string
589			switch c := s.completion[i]; {
590			case c != nil && *c <= t.deadline:
591				deadlineStatus = "met"
592			case c != nil:
593				deadlineStatus = "missed"
594			case t.deadline <= s.horizon:
595				deadlineStatus = "missed"
596			default:
597				deadlineStatus = "pending"
598			}
599			received := s.received[i]
600			if received == nil {
601				received = []mboxReceived{}
602			}
603			results[i] = mboxTaskResult{
604				Executed:       s.executed[i],
605				Completion:     s.completion[i],
606				State:          state,
607				BlockedAction:  blockedAction,
608				BlockedOn:      blockedOn,
609				Received:       received,
610				DeadlineStatus: deadlineStatus,
611			}
612		}
613	
614		status := "horizon"
615		switch {
616		case s.allCompleted():
617			status = "completed"
618		case stalled:
619			status = "stalled"
620		}
621	
622		return mboxResponse{
623			Status:    status,
624			StoppedAt: s.now,
625			Timeline:  timeline,
626			Results:   results,
627		}
628	}
629

