88		if !ok {
89			writeAnalyzeError(w, http.StatusUnprocessableEntity, "validation_failed")
90			return
91		}
92		w.Header().Set("Content-Type", "application/json; charset=utf-8")
93		w.WriteHeader(http.StatusOK)
94		_ = json.NewEncoder(w).Encode(simulateMutex(tasks, *req.Horizon))
95	}
96	
97	// validateMutexRequest enforces the one-shot task constraints (without
98	// execution) plus the action-program rules: exactly one verb per action,
99	// positive run microseconds, id-shaped mutex names, balanced nesting (no
100	// duplicate acquire, no unmatched release, nothing held at the end) and an
101	// int64-wide run total.
102	func validateMutexRequest(req *mutexRequest) ([]mutexTask, bool) {
103		if req.Horizon == nil || *req.Horizon <= 0 || *req.Horizon > maxHorizon {
104			return nil, false
105		}
106		if req.Tasks == nil || len(*req.Tasks) == 0 || len(*req.Tasks) > maxTasks {
107			return nil, false
108		}
109		horizon := *req.Horizon
110		tasks := make([]mutexTask, 0, len(*req.Tasks))
111		ids := make(map[string]struct{}, len(*req.Tasks))
112		var totalRun int64
113		for i := range *req.Tasks {
114			in := (*req.Tasks)[i]
115			if !validTaskID(in.ID) {
116				return nil, false
117			}
118			if _, dup := ids[in.ID]; dup {
119				return nil, false
120			}
121			ids[in.ID] = struct{}{}
122			if in.Priority == nil || *in.Priority < 0 || *in.Priority > 255 {
123				return nil, false
124			}
125			if in.Release == nil || *in.Release < 0 || *in.Release >= horizon {
126				return nil, false
127			}
128			if in.Deadline == nil || *in.Deadline <= *in.Release {
129				return nil, false
130			}
131			if in.Actions == nil || len(*in.Actions) == 0 || len(*in.Actions) > maxMutexActions {
132				return nil, false
133			}
134	
135			actions := make([]mutexAction, 0, len(*in.Actions))
136			held := make(map[string]struct{})
137			var taskRun int64
138			for j := range *in.Actions {
139				ai := (*in.Actions)[j]
140				verbs := 0
141				if ai.Run != nil {
142					verbs++
143				}
144				if ai.Lock != nil {
145					verbs++
146				}
147				if ai.Unlock != nil {
148					verbs++
149				}
150				if verbs != 1 {
151					return nil, false
152				}
153				switch {
154				case ai.Run != nil:
155					if *ai.Run <= 0 {
156						return nil, false
157					}
158					var ok bool
159					taskRun, ok = saturatingAdd(taskRun, *ai.Run)
160					if !ok {
161						return nil, false
162					}
163					actions = append(actions, mutexAction{kind: mutexActRun, run: *ai.Run})
164				case ai.Lock != nil:
165					name := *ai.Lock
166					if !validTaskID(name) {
167						return nil, false
168					}
169					if _, dup := held[name]; dup {
170						return nil, false
171					}
172					held[name] = struct{}{}
173					actions = append(actions, mutexAction{kind: mutexActLock, name: name})
174				default:
175					name := *ai.Unlock
176					if !validTaskID(name) {
177						return nil, false
178					}
179					if _, ok := held[name]; !ok {
180						return nil, false
181					}
182					delete(held, name)
183					actions = append(actions, mutexAction{kind: mutexActUnlock, name: name})
184				}
185			}
186			if len(held) != 0 {
187				return nil, false
188			}
189			var ok bool
190			totalRun, ok = saturatingAdd(totalRun, taskRun)
191			if !ok {
192				return nil, false
193			}
194			tasks = append(tasks, mutexTask{
195				id:       in.ID,
196				priority: *in.Priority,
197				release:  *in.Release,
198				deadline: *in.Deadline,
199				actions:  actions,
200			})
201		}
202		return tasks, true
203	}
204	
205	// mutexSegment is an unmerged run interval recorded by the simulation.
206	type mutexSegment struct {
207		index      int
208		start, end int64
209		eff        int64
210	}
211	
212	// mutexSim is an event-driven single-core simulation with priority
213	// inheritance. Time advances only through run actions; lock, unlock and
214	// completion happen at a single instant. The wait-for graph maps a blocked
215	// task (waiter) to the owner of the mutex it is blocked on.
216	type mutexSim struct {
217		tasks   []mutexTask
218		n       int
219		horizon int64
220	
221		owner   map[string]int    // mutex -> owning task
222		waiters map[string][]int  // mutex -> blocked tasks
223		locksOf []map[string]bool // task -> owned mutexes
224	
225		blockedM  []string // "" when not blocked
226		blockTime []int64
227		pc        []int   // next action to interpret
228		runRem    []int64 // remainder of the run action at pc
229	
230		released   []bool
231		completed  []bool
232		executed   []int64
233		completion []*int64
234		eff        []int64
235	
236		order     []int // tasks sorted by (release, input index)
237		nextRel   int
238		segs      []mutexSegment
239		current   int
240		now       int64
241		deadCycle []int
242	}
243	
244	func simulateMutex(tasks []mutexTask, horizon int64) mutexResponse {
245		n := len(tasks)
246		s := &mutexSim{
247			tasks:      tasks,
248			n:          n,
249			horizon:    horizon,
250			owner:      make(map[string]int),
251			waiters:    make(map[string][]int),
252			locksOf:    make([]map[string]bool, n),
253			blockedM:   make([]string, n),
254			blockTime:  make([]int64, n),
255			pc:         make([]int, n),
256			runRem:     make([]int64, n),
257			released:   make([]bool, n),
258			completed:  make([]bool, n),
259			executed:   make([]int64, n),
260			completion: make([]*int64, n),
261			eff:        make([]int64, n),
262			current:    -1,
263		}
264		for i := range s.locksOf {
265			s.locksOf[i] = make(map[string]bool)
266			s.eff[i] = tasks[i].priority
267		}
268		s.order = make([]int, n)
269		for i := range s.order {
270			s.order[i] = i
271		}
272		sort.Slice(s.order, func(a, b int) bool {
273			ia, ib := s.order[a], s.order[b]
274			if tasks[ia].release != tasks[ib].release {
275				return tasks[ia].release < tasks[ib].release
276			}
277			return ia < ib
278		})
279	
280		deadlocked := false
281	loop:
282		for {
283			s.releaseUpTo()
284	
285			// After any state change, first drain the current task's consecutive
286			// zero-duration actions, then schedule.
287			if s.current != -1 {
288				if s.settle(s.current) {
289					deadlocked = true
290					break
291				}
292				if !s.runnable(s.current) {
293					s.current = -1
294				}
295			}
296	
297			if s.current == -1 {
298				best := s.pickBest()
299				if best == -1 {
300					// Nothing runnable: jump to the next release or the horizon.
301					if s.nextRel >= n {
302						s.now = horizon
303						break loop
304					}
305					s.now = tasks[s.order[s.nextRel]].release
306					continue
307				}
308				s.current = best
309				if s.settle(best) {
310					deadlocked = true
311					break
312				}
313				if !s.runnable(best) {
314					s.current = -1
315					continue
316				}
317			}
318	
319			// A freshly selected task's zero-duration chain (or the previous
320			// current task's chain) can hand a mutex to a strictly higher
321			// effective-priority task at the same instant. Re-resolve until the
322			// selection is stable; equal priority never preempts.
323			for {
324				best := s.pickBest()
325				if best != -1 && best != s.current && s.eff[best] < s.eff[s.current] {
326					s.current = best
327					if s.settle(best) {
328						deadlocked = true
329						break loop
330					}
331					if !s.runnable(best) {
332						s.current = -1
333						continue loop
334					}
335					continue
336				}
337				break
338			}
339	
340			if s.now >= horizon {
341				break
342			}
343			cur := s.current
344			// Advance until the run completes, the horizon cuts it, or a strictly
345			// higher base-priority task releases. Effective priorities are stable
346			// across a run: wait edges change only via zero-duration actions.
347			rem := s.runRem[cur]
348			length := rem
349			if avail := horizon - s.now; length > avail {
350				length = avail
351			}
352			end := s.now + length
353			for k := s.nextRel; k < n; k++ {
354				j := s.order[k]
355				if tasks[j].priority < s.eff[cur] &&
356					tasks[j].release > s.now && tasks[j].release < end {
357					end = tasks[j].release
358				}
359			}
360			s.segs = append(s.segs, mutexSegment{index: cur, start: s.now, end: end, eff: s.eff[cur]})
361			delta := end - s.now
362			s.executed[cur] += delta
363			s.now = end
364			if rem -= delta; rem > 0 {
365				s.runRem[cur] = rem
366				continue
367			}
368			s.runRem[cur] = 0
369			s.pc[cur]++
370			if s.now >= horizon {
371				// The run ends exactly at the horizon: matching the one-shot
372				// baseline, completion at the boundary is observable. Releases
373				// strictly before the horizon are already in effect, so account for
374				// them before draining this task's trailing zero-duration actions
375				// once. Nothing else gets to run at or past the horizon.
376				s.releaseUpTo()
377				if s.settle(cur) {
378					deadlocked = true
379				}
380				break
381			}
382		}
383	
384		return s.buildResponse(deadlocked)
385	}
386	
387	// settle drains the task's consecutive zero-duration actions. It stops when
388	// the task faces a run action (arming its remainder), blocks, or completes.
389	// It reports whether the blocking action closed a wait-for cycle.
390	func (s *mutexSim) settle(i int) bool {
391		for {
392			t := s.tasks[i]
393			if s.pc[i] >= len(t.actions) {
394				s.completed[i] = true
395				now := s.now
396				s.completion[i] = &now
397				return false
398			}
399			a := t.actions[s.pc[i]]
400			switch a.kind {
401			case mutexActRun:
402				if s.runRem[i] == 0 {
403					s.runRem[i] = a.run
404				}
405				return false
406			case mutexActLock:
407				m := a.name
408				if owner, ok := s.owner[m]; ok {
409					if owner == i {
410						// Granted via handoff while blocked at this action.
411						s.pc[i]++
412						continue
413					}
414					cycle := s.cycleOnBlock(i, owner)
415					s.blockedM[i] = m
416					s.blockTime[i] = s.now
417					s.waiters[m] = append(s.waiters[m], i)
418					if cycle != nil {
419						s.deadCycle = cycle
420						return true
421					}
422					s.recompute()
423					return false
424				}
425				s.owner[m] = i
426				s.locksOf[i][m] = true
427				s.pc[i]++
428			case mutexActUnlock:
429				s.handoff(a.name, i)
430				s.pc[i]++
431			}
432		}
433	}
434	
435	// waitersOn lists the blocked tasks directly waiting on mutexes owned by x
436	// (the predecessor direction of the wait-for graph). A task blocks on at most
437	// one mutex, so no member repeats. Order is irrelevant: inheritance takes the
438	// minimum and the graph is acyclic between recomputations.
439	func (s *mutexSim) waitersOn(x int) []int {
440		var out []int
441		for m := range s.locksOf[x] {
442			out = append(out, s.waiters[m]...)
443		}
444		return out
445	}
446	
447	// blockTarget is the outgoing wait-for edge of x: the owner of the mutex x is
448	// blocked on, or -1 when x is not blocked.
449	func (s *mutexSim) blockTarget(x int) int {
450		if s.blockedM[x] == "" {
451			return -1
452		}
453		return s.owner[s.blockedM[x]]
454	}
455	
456	// cycleOnBlock checks whether adding the edge waiter -> holder closes a cycle
457	// in the wait-for graph. Every task has at most one outgoing edge, so the
458	// existing graph is a forest of chains (any earlier cycle would already have
459	// stopped the simulation): holder reaches waiter at most once. The returned
460	// cycle follows the wait direction and starts at the earliest input-order task.
461	func (s *mutexSim) cycleOnBlock(waiter, holder int) []int {
462		chain := []int{holder}
463		cur := holder
464		for {
465			next := s.blockTarget(cur)
466			if next == -1 {
467				return nil
468			}
469			if next == waiter {
470				break
471			}
472			chain = append(chain, next)
473			cur = next
474		}
475		cycle := append([]int{waiter}, chain...)
476		first := 0
477		for k := 1; k < len(cycle); k++ {
478			if cycle[k] < cycle[first] {
479				first = k
480			}
481		}
482		return append(append([]int(nil), cycle[first:]...), cycle[:first]...)
483	}
484	
485	// handoff releases m from its owner and transfers it to the waiter with the
486	// highest effective priority, breaking ties by block time then input index.
487	// Waiter effective priorities cannot depend on the outgoing owner's edge
488	// (waiters have no edge toward a holder of m), so the pre-unlock values stay
489	// valid for the selection.
490	func (s *mutexSim) handoff(m string, from int) {
491		ws := s.waiters[m]
492		delete(s.locksOf[from], m)
493		if len(ws) == 0 {
494			delete(s.owner, m)
495			s.recompute()
496			return
497		}
498		w := ws[0]
499		for _, x := range ws[1:] {
500			if s.eff[x] < s.eff[w] ||
501				(s.eff[x] == s.eff[w] && s.blockTime[x] < s.blockTime[w]) ||
502				(s.eff[x] == s.eff[w] && s.blockTime[x] == s.blockTime[w] && x < w) {
503				w = x
504			}
505		}
506		s.owner[m] = w
507		s.locksOf[w][m] = true
508		remaining := make([]int, 0, len(ws)-1)
509		for _, x := range ws {
510			if x != w {
511				remaining = append(remaining, x)
512			}
513		}
514		s.waiters[m] = remaining
515		s.blockedM[w] = ""
516		s.recompute()
517	}
518	
519	// recompute derives every effective priority as the minimum of the task's own
520	// priority and the effective priorities of the direct waiters on its mutexes;
521	// the DFS therefore covers indirect inheritance transitively.
522	func (s *mutexSim) recompute() {
523		mark := make([]int8, s.n)
524		var dfs func(int) int64
525		dfs = func(i int) int64 {
526			if mark[i] == 2 {
527				return s.eff[i]
528			}
529			mark[i] = 1
530			best := s.tasks[i].priority
531			for _, w := range s.waitersOn(i) {
532				if v := dfs(w); v < best {
533					best = v
534				}
535			}
536			mark[i] = 2
537			s.eff[i] = best
538			return best
539		}
540		for i := 0; i < s.n; i++ {
541			dfs(i)
542		}
543	}
544	
545	// pickBest selects the runnable task with the highest effective priority,
546	// breaking ties by release time then input index.
547	func (s *mutexSim) pickBest() int {
548		best := -1
549		for i := 0; i < s.n; i++ {
550			if !s.released[i] || s.completed[i] || s.blockedM[i] != "" {
551				continue
552			}
553			if best == -1 {
554				best = i
555				continue
556			}
557			a, b := s.tasks[i], s.tasks[best]
558			if s.eff[i] < s.eff[best] ||
559				(s.eff[i] == s.eff[best] && a.release < b.release) ||
560				(s.eff[i] == s.eff[best] && a.release == b.release && i < best) {
561				best = i
562			}
563		}
564		return best
565	}
566	
567	func (s *mutexSim) runnable(i int) bool {
568		return s.released[i] && !s.completed[i] && s.blockedM[i] == "" && s.runRem[i] > 0
569	}
570	
571	func (s *mutexSim) releaseUpTo() {
572		for s.nextRel < s.n && s.tasks[s.order[s.nextRel]].release <= s.now {
573			s.released[s.order[s.nextRel]] = true
574			s.nextRel++
575		}
576	}
577	
578	func (s *mutexSim) buildResponse(deadlocked bool) mutexResponse {
579		timeline := make([]mutexTimelineInterval, 0, len(s.segs))
580		for _, seg := range s.segs {
581			last := len(timeline) - 1
582			if last >= 0 &&
583				timeline[last].TaskID == s.tasks[seg.index].id &&
584				timeline[last].EffectivePriority == seg.eff &&
585				timeline[last].End == seg.start {
586				timeline[last].End = seg.end
587				continue
588			}
589			timeline = append(timeline, mutexTimelineInterval{
590				TaskID:            s.tasks[seg.index].id,
591				Start:             seg.start,
592				End:               seg.end,
593				EffectivePriority: seg.eff,
594			})
595		}
596	
597		results := make([]mutexTaskResult, s.n)
598		allCompleted := true
599		for i, t := range s.tasks {
600			state := "ready"
601			switch {
602			case s.completed[i]:
603				state = "completed"
604			case s.blockedM[i] != "":
605				state = "blocked"
606			case !s.released[i]:
607				state = "unreleased"
608			}
609			if state != "completed" {
610				allCompleted = false
611			}
612			var blockedOn *string
613			if state == "blocked" {
614				m := s.blockedM[i]
615				blockedOn = &m
616			}
617			var deadlineStatus string
618			switch c := s.completion[i]; {
619			case c != nil && *c <= t.deadline:
620				deadlineStatus = "met"
621			case c != nil:
622				deadlineStatus = "missed"
623			case t.deadline <= s.horizon:
624				deadlineStatus = "missed"
625			default:
626				deadlineStatus = "pending"
627			}
628			results[i] = mutexTaskResult{
629				Executed:       s.executed[i],
630				Completion:     s.completion[i],
631				State:          state,
632				BlockedOn:      blockedOn,
633				DeadlineStatus: deadlineStatus,
634			}
635		}
636	
637		status := "horizon"
638		if deadlocked {
639			status = "deadlocked"
640		} else if allCompleted {
641			status = "completed"
642		}
643	
644		resp := mutexResponse{
645			Status:   status,
646			Timeline: timeline,
647			Results:  results,
648		}
649		if deadlocked {
650			at := s.now
651			resp.DeadlockAt = &at
652			cycle := make([]string, len(s.deadCycle))
653			for k, idx := range s.deadCycle {
654				cycle[k] = s.tasks[idx].id
655			}
656			resp.Cycle = cycle
657		}
658		return resp
659	}
660

